import { QUIZ_ICONS } from "@/lib/quiz-icons";
// Quiz illustrations (Phosphor duotone, generated by scripts/build-quiz-icons.mjs).
// Static SVG bodies from the repo, never user input.
export function QuizIcon({ emoji, big = false }: { emoji: string; big?: boolean }) {
  const body = QUIZ_ICONS[emoji];
  if (!body) throw new Error(`No quiz illustration for ${emoji}: run scripts/build-quiz-icons.mjs`);
  return (
    <svg
      className={big ? "quiz-icon big" : "quiz-icon"}
      viewBox="0 0 256 256"
      aria-hidden
      dangerouslySetInnerHTML={{ __html: body }}
    />
  );
}
